<template>
 <ThemePage><view class="ledger-page" data-distribution-ledgers>
  <view v-if="!state.routeValid" class="ledger-state ledger-error" role="alert">记录类型无效，请从分销中心重新进入</view>
  <template v-else>
   <view class="ledger-header"><view v-if="state.mode==='commission'" class="search-pill"><text class="search-icon">⌕</text><input v-model="state.keyword" confirm-type="search" maxlength="128" placeholder="搜索用户名称" aria-label="搜索用户名称" @confirm="state.search"/><button class="search-button" @tap="state.search">搜索</button></view>
    <view class="time-slot"><view class="time-presets"><button v-for="item in periods" :key="item.value" :class="{selected:state.period===item.value}" @tap="state.choosePeriod(item.value)">{{ item.label }}</button></view><button class="custom-toggle" :class="{selected:state.period==='custom'}" @tap="state.customOpen=!state.customOpen">自定义时间⌄</button></view>
    <view v-if="state.customOpen" class="custom-range"><view class="date-pickers"><picker mode="date" :value="state.startDay" start="1970-01-02" end="2038-01-18" @change="changeStart"><view>开始日期 <text>{{ state.startDay }}</text></view></picker><picker mode="date" :value="state.stopDay" start="1970-01-02" end="2038-01-18" @change="changeStop"><view>结束日期 <text>{{ state.stopDay }}</text></view></picker></view><button class="apply-range" @tap="state.applyCustom">查询所选日期</button></view>
   </view>
   <view v-if="state.period==='custom' && !state.customOpen" class="range-caption">{{ state.appliedDates.start }} 至 {{ state.appliedDates.stop }}（上海时间）</view>
   <view v-if="state.filterError" class="ledger-state ledger-error" role="alert">{{ state.filterError }}</view>
   <view v-if="!state.loggedIn" class="ledger-state"><view>登录后查看{{ state.title }}</view><button class="ledger-control" @tap="state.login">去登录</button></view>
   <template v-else>
    <view v-if="state.loaded && state.mode==='commission'" class="ledger-summary">支出：¥<text>{{ state.expend }}</text>　收入：¥<text>{{ state.income }}</text></view>
    <view v-if="state.loaded" class="record-count">共 {{ state.count }} 条记录</view>
    <view v-if="state.items.length" class="ledger-list"><view v-for="row in state.items" :key="row.id" class="ledger-row" :data-ledger-id="row.id"><view class="row-detail"><view class="row-title">{{ row.title }}<text v-if="row.review" class="review-badge" :class="row.withdrawal_status===-1?'rejected':row.withdrawal_status===0?'pending':'approved'">{{ row.review }}</text></view><view v-if="row.withdrawal_status===-1 && row.withdrawal_message" class="rejection-reason">原因：{{ row.withdrawal_message }}</view><view class="row-time">{{ row.time }}</view></view><view class="row-amount">{{ row.amount }}</view></view></view>
    <view v-if="state.loading" class="ledger-state" role="status">记录读取中…</view><view v-if="state.error" class="ledger-state ledger-error" role="alert">{{ state.error }}</view>
    <view v-if="state.loaded && !state.loading && !state.error && !state.items.length" class="ledger-empty"><image src="/static/php-points/noOrder.gif" mode="aspectFit"/><view>暂无数据～</view></view>
    <button v-if="state.error" class="ledger-control" :disabled="state.loading" @tap="state.retry">重试当前页</button><button v-if="state.hasMore && !state.error" class="ledger-control" :disabled="state.loading" @tap="state.load(true)">{{ state.loading?'读取中…':'加载更多' }}</button>
    <view v-if="state.loaded && state.items.length && !state.hasMore && !state.loading && !state.error" class="ledger-state">{{ state.page===500?'已显示前10000条记录':'没有更多内容啦～' }}</view><button class="ledger-control" :disabled="state.loading" @tap="state.refresh">刷新记录</button>
   </template>
  </template>
 </view></ThemePage>
</template>
<script setup lang="ts">
import {reactive} from 'vue';
import ThemePage from '@/components/ThemePage.vue';
import {useDistributionLedgers} from '@/composables/useDistributionLedgers';
import type {DistributionReportPeriod} from '@/utils/distributionReportFilters';
const state=reactive(useDistributionLedgers());
const periods:{value:Exclude<DistributionReportPeriod,'custom'>;label:string}[]=[{value:'all',label:'全部'},{value:'today',label:'今日'},{value:'yesterday',label:'昨日'},{value:'seven',label:'近7日'}];
function changeStart(event:{detail:{value:string}}){state.startDay=event.detail.value;}
function changeStop(event:{detail:{value:string}}){state.stopDay=event.detail.value;}
</script>
